import axios from "axios";
import MaterialTable, { MTableToolbar } from "material-table";
import { Spinner } from "reactstrap";
import React, { Component } from "react";
import { Modal, ModalHeader, ModalBody } from "reactstrap";
import { connect } from "react-redux";
import PropTypes from "prop-types";
import { login, loadUser } from "../../actions/authActions";
import { clearErrors } from "../../actions/errorActions";
import store from "../../store";
import { Button } from "@material-ui/core";

class UserAccessModal extends Component {
  state = {
    modal: false,
    rowData: [],
    tableLoaded: false,

    columns: [
      { title: "ID", field: "id", editable: "never" },
      { title: "Name", field: "name" },
      {
        title: "Select",
        field: "created_by",
        editable: "never",
        initialEditValue: "guest  "
      }
    ]
  };
  componentDidMount() {
    this.retrieveFromDb();
  }
  toggle = () => {
    this.setState({
      modal: !this.state.modal
    });
  };
  retrieveFromDb = () => {
    this.setState(state => ({
      tableLoaded: false,
      rowData: state.rowData
    }));
    axios
      .get("/api/userList")
      .then(res => {
        var rowData = res.data.map((x, index) => {
          return {
            id: x._id,
            name: x.name
          };
        });

        this.setState(state => ({
          tableLoaded: true,
          rowData
        }));
      })
      .catch(err => console.log(err));
  };

  render() {
    return (
      <div>
        <Button
          className="mt-2 mb-3"
          variant="contained"
          color="primary"
          onClick={this.toggle}
        >
          Assign Users
        </Button>
        <Modal size={"lg"} isOpen={this.state.modal} toggle={this.toggle}>
          <ModalHeader toggle={this.toggle}>Assign Users</ModalHeader>
          <ModalBody>
            {this.state.tableLoaded ? (
              <div>
                <MaterialTable
                  columns={this.state.columns}
                  data={this.state.rowData}
                  title="Choose Users"
                  options={{
                    search: false,
                    showTitle: true,
                    toolbar: true
                  }}
                  //////
                />
                <div className="mb-3"> </div>
                <MaterialTable
                  columns={this.state.columns}
                  data={this.state.rowData}
                  title="Selected Users"
                  options={{
                    search: false,
                    showTitle: true,
                    toolbar: true
                  }}
                  //////
                />

                <div
                  style={{
                    display: "flex",
                    flexDirection: "row-reverse"
                  }}
                >
                  <Button
                    className="mt-3 mb-1"
                    variant="contained"
                    color="primary"
                    onClick={this.toggle}
                  >
                    Assign Users
                  </Button>
                </div>
              </div>
            ) : (
              <div
                style={{
                  display: "flex",
                  justifyContent: "center"
                }}
              >
                <Spinner animation="border" />
              </div>
            )}
          </ModalBody>
        </Modal>
      </div>
    );
  }
}

const mapStateToProps = state => ({
  isAutheticated: state.auth.isAutheticated,
  error: state.error
});

export default connect(mapStateToProps, null)(UserAccessModal);
//mapStateToProps gets state variables from elsewhere in the app.
//the stuff in the curly braces are methods brought in to modify state in other parts of the app
//all these things will be declared in the component props
